import { alpha } from "@mui/material";
import { getValue } from "../../../tokens";
export const ThemedPaper = {
    defaultProps: {
        elevation: 2,
    },
    styleOverrides: {
        elevation: {
            backgroundImage: "none",
        },
        root: ({ theme }) => {
            const { border: { focusBorder }, } = getValue("semantic", theme.palette.brand, theme.palette.mode);
            return {
                border: `1px solid ${alpha(focusBorder, 0.12)}`,
            };
        },
    },
};
